\label{Pro:F_n+E_n}
	Let $M$ be a closed subspace of $\omega$. Then, for every non-increasing sequence $(E_n)_{n \geq 1}$ of closed subspaces of finite codimension in $M$, there exists a sequence of finite-dimensional subspaces $(F_n)_{n \geq 1}$ such that:
	\begin{enumerate}[label=$\bullet$]
		\item $M=F_1\oplus E_1$ and $E_n=F_{n+1}\oplus E_{n+1}$ for every $n \geq 1$;

		\item the sequence $(\operatorname{val}(F_n))_{n \geq 1}$ tends to infinity and hence every series $\sum_{n=1}^{\infty} f_n$ is convergent whenever $(f_n)_{n \geq 1}$ is a sequence with $f_n \in F_n$ for each $n \geq 1$;

		\item for every $x \in M$ there exist a unique sequence $(f_n)_{n \geq 1}$, with $f_n\in F_n$ for each $n \geq 1$, and a unique vector $e \in \bigcap_{n \geq 1} E_n$ such that $x = \sum_{n=1}^{\infty} f_n + e$.
\end{enumerate}

\label{The:X+omega.pos-exp}
	If a Banach space $X$ admits a basic sequence $(u_k)_{k \geq 1}$ such that:
	\begin{enumerate}[label=$\bullet$]
		\item $\inf_{k \geq 1} \|u_k\|>0$;

		\item the closed subspace $M : =\overline{\operatorname{span}}\{ u_k : k \geq 1 \}$ is topologically complemented in $X$;

		\item and the forward shift defined along $(u_k)_{k \geq 1}$ is continuous on $M$;
	\end{enumerate}
	then the Fr\'echet space $X\oplus\omega$ admits a (metrically) positively expansive operator.

\label{The:X+omega.exp}
	If a Banach space $X$ admits a basic sequence $(u_k)_{k \geq 1}$ such that:
	\begin{enumerate}[label=$\bullet$]
		\item $\inf_{k \geq 1}\|u_k\|>0$;

		\item the closed subspace $M := \overline{\operatorname{span}}\{ u_k : k \geq 1 \}$ is topologically complemented in $X$;

		\item the backward and forward shifts along $(u_k)_{k \geq 1}$ are continuous on $M$;
	\end{enumerate}
	then $X\oplus\omega$ admits an invertible positively expansive (and hence expansive) operator.

The Fr\'echet space $X\oplus\omega$ admits an invertible positively expansive operator and thus an expansive operator in any of the following cases: 
	\begin{enumerate}[label=$\bullet$]
		\item $X=\ell^p$ with $p \in [1,\infty[$;

		\item $X=c_0$;

		\item $X$ is an infinite-dimensional Hilbert space;

		\item $X$ is a non-reflexive Banach space admitting an unconditional basis.
	\end{enumerate}
